import{_ as a,b as o,e as i,a8 as n}from"./chunks/framework.BXWQBDlf.js";const m=JSON.parse('{"title":"Examples & Tutorials","description":"","frontmatter":{"date":1789160173000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"examples/index.md","filePath":"examples/index.md","lastUpdated":1789160173000,"timestamp":1789160173000,"datetime":"2026-09-11T20:56:13.000Z"}'),t={name:"examples/index.md"};function r(s,e,d,c,l,p){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="examples-tutorials" tabindex="-1">Examples &amp; Tutorials <a class="header-anchor" href="#examples-tutorials" aria-label="Permalink to &quot;Examples &amp; Tutorials&quot;">​</a></h1><p>Welcome to the Graphics32 Examples &amp; Tutorials section! Whether you are completely new to Graphics32 or looking for practical code snippets to perform common graphics tasks, these beginner-friendly guides provide step-by-step explanations and Pascal code examples.</p><hr><h2 id="tutorial-guides" tabindex="-1">Tutorial Guides <a class="header-anchor" href="#tutorial-guides" aria-label="Permalink to &quot;Tutorial Guides&quot;">​</a></h2><ol><li><p><strong><a href="./basic-drawing">Basic Drawing &amp; Shapes</a></strong> Learn how to instantiate <code>TBitmap32</code>, clear backgrounds, set canvas dimensions, draw primitive lines, rectangles, and ellipses, and understand clipping method suffixes (<code>*S</code>, <code>*TS</code>).</p></li><li><p><strong><a href="./alpha-blending">Alpha Blending &amp; Transparency</a></strong> Explore 32-bit ARGB colors (<code>TColor32</code>), translucent color constants, <code>DrawMode</code> settings (<code>dmOpaque</code>, <code>dmBlend</code>), combine modes (<code>cmAdd</code>, <code>cmModulate</code>), and global <code>MasterAlpha</code> controls.</p></li><li><p><strong><a href="./pixel-manipulation">Fast Pixel Access &amp; Direct Manipulation</a></strong> Master high-performance pixel operations using bounds-checked <code>PixelS</code>, unchecked <code>Pixel</code>, row pointers via <code>ScanLine[Y]</code>, and whole-image flat array processing with <code>Bits</code>.</p></li><li><p><strong><a href="./resampling-and-scaling">Image Resampling &amp; High-Quality Scaling</a></strong> Understand nearest-neighbor stretching vs convolution resampling, configuring <code>TKernelResampler</code>, choosing optimal filter kernels (<code>Lanczos</code>, <code>Mitchell</code>, <code>Bicubic</code>), and using procedural <code>Resample</code> helpers.</p></li><li><p><strong><a href="./affine-transformations">Affine Transformations</a></strong> Learn how <code>TAffineTransformation</code> matrices work to rotate bitmaps around custom center points, scale, skew, and translate surfaces, and calculate exact transformed bounding boxes with <code>GetTransformedBounds</code>.</p></li><li><p><strong><a href="./vector-polygons">Vector Polygons &amp; Path Drawing</a></strong> Discover sub-pixel float coordinates (<code>TFloatPoint</code>), anti-aliased polygon rendering with VPR (<code>PolygonFS</code>), stroking thick paths with customizable line joins and caps, and multi-contour hole filling.</p></li><li><p><strong><a href="./color-gradients">Color Gradients &amp; Fill Samplers</a></strong> Configure gradient color stops with <code>TColor32Gradient</code>, fill vector polygons with <code>TLinearGradientPolygonFiller</code> and <code>TRadialGradientPolygonFiller</code>, and control gradient repetitions with <code>WrapMode</code>.</p></li><li><p><strong><a href="./working-with-layers">Working with Interactive Layers in TImage32</a></strong> Build interactive desktop applications using <code>TImage32</code>, add positionable <code>TBitmapLayer</code> instances, enable interactive mouse dragging and resizing handles with <code>TRubberbandLayer</code>, and manage z-order.</p></li><li><p><strong><a href="./loading-and-saving">Loading, Saving &amp; Image Formats</a></strong> Load and save 32-bit images across PNG, JPEG, BMP, and PSD formats from disk and memory streams, preserve alpha channels with <code>ResetAlpha</code>, and convert pixels between VCL/FCL <code>TBitmap</code> and <code>TBitmap32</code>.</p></li><li><p><strong><a href="./custom-painting-repaint">Repaint Optimization &amp; Custom Canvas Drawing</a></strong> Optimize rendering performance with <code>BeginUpdate</code>/<code>EndUpdate</code> batching, invalidate partial sub-regions using <code>Changed(TRect)</code>, draw non-destructive UI overlays with <code>TImage32.OnPaintStage</code>, and build smooth animation loops.</p></li></ol>',5)])])}const h=a(t,[["render",r]]);export{m as __pageData,h as default};
